class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        N = 101
        is_p = [True] * N
        is_p[0] = is_p[1] = False
        for i in range(2, N):
            if is_p[i]:
                for j in range(i * i, N, i):
                    is_p[j] = False
        first = last = -1
        for i, x in enumerate(nums):
            if is_p[x]:
                if first == -1: first = i
                last = i
        return last - first

