class Solution {
public:
    int maximumPrimeDifference(vector<int>& nums) {
        bool isp[101]; fill(isp, isp + 101, true);
        isp[0] = isp[1] = false;
        for (int i = 2; i <= 100; i++)
            if (isp[i]) for (int j = i * i; j <= 100; j += i) isp[j] = false;
        int first = -1, last = -1;
        for (int i = 0; i < (int)nums.size(); i++)
            if (isp[nums[i]]) { if (first < 0) first = i; last = i; }
        return last - first;
    }
};

