class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def prime(x):
            if x < 2: return False
            d = 2
            while d * d <= x:
                if x % d == 0: return False
                d += 1
            return True
        first = last = -1
        for i, x in enumerate(nums):
            if prime(x):
                if first == -1: first = i
                last = i
        return last - first

